">By ${safe(d.publishAnonymously?'Guest Writer':d.author)} · ${safe(d.reference)} · Published</div></div><div class=\"whdc-row-actions\"><button class=\"btn\" type=\"button\" data-guest-read=\"${safe(d.publishedId)}\">Read</button><button class=\"btn\" type=\"button\" data-guest-edit=\"${safe(d.publishedId)}\">Edit</button><button class=\"btn\" type=\"button\" data-assign-editor=\"writer:${safe(d.id)}\">Assign Editor</button><button class=\"btn\" type=\"button\" data-guest-delete=\"${safe(d.id)}\">Delete</button></div></div>`).join('')}\n       ${!(guestTab==='pending'?pending.length:guestTab==='published'?guestPublished.length:pending.length+guestPublished.length)?'<p>No submissions in this tab.</p>':''}\n      </div>\n     </section>`:``}`;\n   if(!submissionsPage){\n     const writerBox=area.querySelector('.whdc-manage-compact');\n     const editorBox=window.__whdcEditorMount||document.getElementById('manageEditors');\n     if(writerBox&&editorBox){\n       let grid=area.querySelector('#whdcManagementGrid');\n       if(!grid){grid=document.createElement('div');grid.id='whdcManagementGrid';writerBox.before(grid)}\n       grid.append(writerBox,editorBox);\n     }\n   }\n   area.querySelectorAll('[data-guest-tab]').forEach(b=>b.onclick=()=>{guestTab=b.dataset.guestTab;draw()});\n   area.querySelectorAll('[data-guest-read]').forEach(b=>b.onclick=()=>{const d=items.find(x=>String(x.id)===b.dataset.guestRead);if(d)openAdminReader(d);else alert('Published devotional not found.')});\n   area.querySelectorAll('[data-guest-edit]').forEach(b=>b.onclick=()=>{const d=items.find(x=>String(x.id)===b.dataset.guestEdit);if(d)openAdminModalEditor(d);else alert('Published devotional not found.')});\n   area.querySelectorAll('[data-guest-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Permanently delete this published guest devotional and its submission record?'))return;try{await api('/api/admin/guest-published/delete',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({id:b.dataset.guestDelete})});publishedSelected.delete(String(b.dataset.guestDelete));await refresh();await draw()}catch(e){alert(e.message)}});\n   area.querySelectorAll('[data-open-approval]').forEach(b=>b.onclick=()=>openReview(b.dataset.openApproval));\n   area.querySelectorAll('[data-publish-approval]').forEach(b=>b.onclick=()=>processReview(b.dataset.publishApproval,'publish'));\n   area.querySelectorAll('[data-revise-approval]').forEach(b=>b.onclick=()=>{openReview(b.dataset.reviseApproval);reviewDialog().querySelector('#whdcReviewNote').focus()});\n   const visiblePending=()=>guestTab==='pending'||guestTab==='all'?pending:[];\n   const visiblePublished=()=>guestTab==='published'||guestTab==='all'?guestPublished:[];\n   const updateApproval=()=>{\n    const n=area.querySelector('#whdcSelectedCount'),pub=area.querySelector('#whdcPublishSelected'),del=area.querySelector('#whdcDeletePublishedSelected'),all=area.querySelector('#whdcSelectAll');\n    const pendingIds=new Set(visiblePending().map(d=>String(d.id))),publishedIds=new Set(visiblePublished().map(d=>String(d.id)));\n    const p=[...approvalSelected].filter(id=>pendingIds.has(id)).length, q=[...publishedSelected].filter(id=>publishedIds.has(id)).length,total=p+q,visibleCount=pendingIds.size+publishedIds.size;\n    if(n)n.textContent=total+' selected';if(pub)pub.disabled=!p;if(del)del.disabled=!q;\n    if(all){all.checked=visibleCount>0&&total===visibleCount;all.indeterminate=total>0&&total<visibleCount}\n   };\n   area.querySelectorAll('[data-select-approval]').forEach(c=>c.onchange=()=>{if(c.checked)approvalSelected.add(c.dataset.selectApproval);else approvalSelected.delete(c.dataset.selectApproval);updateApproval()});\n   area.querySelectorAll('[data-select-published]').forEach(c=>c.onchange=()=>{if(c.checked)publishedSelected.add(c.dataset.selectPublished);else publishedSelected.delete(c.dataset.selectPublished);updateApproval()});\n   const all=area.querySelector('#whdcSelectAll');if(all)all.onchange=()=>{for(const d of visiblePending()){if(all.checked)approvalSelected.add(String(d.id));else approvalSelected.delete(String(d.id))}for(const d of visiblePublished()){if(all.checked)publishedSelected.add(String(d.id));else publishedSelected.delete(String(d.id))}area.querySelectorAll('[data-select-approval],[data-select-published]').forEach(c=>c.checked=all.checked);updateApproval()};\n   const clear=area.querySelector('#whdcClearSelected');if(clear)clear.onclick=()=>{for(const d of visiblePending())approvalSelected.delete(String(d.id));for(const d of visiblePublished())publishedSelected.delete(String(d.id));area.querySelectorAll('[data-select-approval],[data-select-published]').forEach(c=>c.checked=false);updateApproval()};\n   const bulk=area.querySelector('#whdcPublishSelected');if(bulk)bulk.onclick=async()=>{const chosen=visiblePending().filter(d=>approvalSelected.has(String(d.id)));if(!chosen.length||!confirm('Publish '+chosen.length+' selected submissions?'))return;bulk.disabled=true;let done=0,errors=[];for(const d of chosen){try{await api('/api/admin/review',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({id:d.id,action:'publish',note:''})});approvalSelected.delete(String(d.id));done++}catch(e){errors.push(d.title+': '+e.message)}}await refresh();await draw();alert(done+' published.'+(errors.length?' Errors: '+errors.join('; '):''))};\n   const bulkDelete=area.querySelector('#whdcDeletePublishedSelected');if(bulkDelete)bulkDelete.onclick=async()=>{const chosen=visiblePublished().filter(d=>publishedSelected.has(String(d.id)));if(!chosen.length||!confirm('Permanently delete '+chosen.length+' selected published guest devotionals and their submission records? This cannot be undone.'))return;bulkDelete.disabled=true;let done=0,errors=[];for(const d of chosen){try{await api('/api/admin/guest-published/delete',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({id:d.id})});publishedSelected.delete(String(d.id));done++}catch(e){errors.push(d.title+': '+e.message)}}await refresh();await draw();alert(done+' deleted.'+(errors.length?' Errors: '+errors.join('; '):''))};\n   updateApproval();\n   area.querySelector('#toggleAddWriter').onclick=()=>{showAddWriter=!showAddWriter;const form=area.querySelector('#addWriter');form.hidden=!showAddWriter;const button=area.querySelector('#toggleAddWriter');button.textContent=showAddWriter?'Cancel':'＋ Add Writer';button.setAttribute('aria-expanded',String(showAddWriter));if(showAddWriter)form.querySelector('input').focus()};\n   area.querySelector('#writerList').ontoggle=e=>{showWriterList=e.target.open};\n   area.querySelectorAll('[data-writer-role-tab]').forEach(b=>b.onclick=()=>{writerRoleTab=b.dataset.writerRoleTab;showWriterList=true;draw()});\n   area.querySelector('#addWriter').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button[type=\"submit\"]'),f=new FormData(form);button.disabled=true;try{await api('/api/admin/writers',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email:f.get('email'),displayName:f.get('displayName')})});showAddWriter=false;await draw();message('Writer added successfully.')}catch(err){alert(err.message);button.disabled=false}};\n   area.querySelectorAll('[data-resend-invitation]').forEach(b=>b.onclick=async()=>{\n    const email=b.dataset.resendInvitation;\n    if(!confirm('Resend the invitation email to '+email+'?'))return;\n    b.disabled=true;\n    const original=b.textContent;b.textContent='Sending…';\n    try{\n     const result=await api('/api/admin/writers/resend-invitation',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email})});\n     alert(result.invitationSent?'Invitation sent successfully.':'The invitation could not be confirmed. Check Cloudflare Observability logs for WHDC email diagnostics.');\n    }catch(err){alert('Unable to resend invitation: '+err.message)}\n    finally{b.disabled=false;b.textContent=original}\n   });\n   area.querySelectorAll('[data-add-editor-role]').forEach(b=>b.onclick=async()=>{\n     const w=writers.find(x=>x.email===b.dataset.addEditorRole);\n     if(!w||!confirm('Give '+w.display_name+' an Editor role as well? Their Writer role will stay unchanged.'))return;\n     b.disabled=true;\n     try{const result=await api('/api/admin/editors',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email:w.email,displayName:w.display_name})});await draw();document.dispatchEvent(new Event('whdc-role-updated'));alert('Editor role added. '+(result.invitationSent?'An editor invitation email was sent.':'The invitation email could not be confirmed. You can resend it from Manage Editors.'));}\n     catch(err){alert(err.message);b.disabled=false}\n   });\n   area.querySelectorAll('[data-deactivate]').forEach(b=>b.onclick=async()=>{if(!confirm('Deactivate this writer?'))return;try{await api('/api/admin/writers/deactivate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email:b.dataset.deactivate})});await draw()}catch(err){alert(err.message)}});\n   area.querySelectorAll('[data-reactivate]').forEach(b=>b.onclick=async()=>{\n    const email=b.dataset.reactivate;\n    if(!confirm('Reactivate '+email+' and restore Writing Dashboard access? No invitation email will be sent.'))return;\n    b.disabled=true;\n    try{await api('/api/admin/writers/reactivate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email})});await draw();alert('Writer reactivated. Their devotionals were preserved.')}catch(err){alert(err.message);b.disabled=false}\n   });\n   area.querySelectorAll('[data-delete-writer]').forEach(b=>b.onclick=async()=>{\n    const email=b.dataset.deleteWriter;\n    if(!confirm('Permanently delete the writer account for '+email+'?\\n\\nTheir access will be revoked, but ALL drafts, submissions, published devotionals, and author credits will be kept.'))return;\n    b.disabled=true;\n    try{await api('/api/admin/writers/delete',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({email})});await draw();alert('Writer removed from Manage Writers. Existing devotionals and any Editor role were preserved.')}catch(err){alert(err.message);b.disabled=false}\n   });\n\n  }\n  await draw();\n }catch(e){console.error('Writer management unavailable:',e);if(submissionsPage)document.querySelector('#adminApp').textContent='Could not load submissions: '+e.message}\n})();\n\n\n// Editor management belongs exclusively to the administrator's dashboard.\n(function(){\n let editors=[],assignments=[],suggestions=[],roleWriters=[];\n let showAddEditor=false,showEditorList=false,editorRoleTab=\"active\";\n const mount=document.createElement('section');mount.className='card';mount.id='manageEditors';window.__whdcEditorMount=mount;\n if(editorNotesPage){\n   const area=document.createElement('section');area.id='editorNotesPage';\n   document.querySelector('main').appendChild(area);\n   let selectedNotes=new Set(),notesTab='pending';\n   const show=()=>{\n     const pending=suggestions.filter(s=>s.status==='pending');\n     const done=assignments.filter(x=>x.status==='completed');\n     const toEdit=assignments.filter(x=>x.status!=='completed');\n     const counts={pending:pending.length,assigned:assignments.length,to_edit:toEdit.length,completed:done.length,all:assignments.length+pending.length};\n     const allRows=[\n       ...pending.map(s=>({type:'suggestion',key:s.source_type+':'+s.devotional_id,title:s.devotional_title||JSON.parse(s.original_json).title||s.devotional_id,source:s.source_type,email:s.editor_email,status:'Needs Approval',item:s})),\n       ...assignments.map(x=>({type:'assignment',key:x.source_type+':'+x.devotional_id,title:x.devotional_title||x.devotional_id,source:x.source_type,email:x.display_name||x.editor_email,status:x.status==='completed'?'Completed':'To Edit',item:x}))\n     ];\n     const shown=allRows.filter(r=>notesTab==='all'||(notesTab==='pending'&&r.type==='suggestion')||(notesTab==='assigned'&&r.type==='assignment')||(notesTab==='to_edit'&&r.type==='assignment'&&r.status==='To Edit')||(notesTab==='completed'&&r.type==='assignment'&&r.status==='Completed'));\n     const selectedVisible=shown.filter(r=>r.type==='suggestion'&&selectedNotes.has(r.key));\n     area.innerHTML=`<div class=\"whdc-editor-admin-page\">\n       <p><a class=\"btn\" href=\"/admin\">← Admin Dashboard</a></p>\n       <div class=\"whdc-editor-bulkbar\"><label><input type=\"checkbox\" id=\"selectAllEditorNotes\" ${shown.filter(r=>r.type==='suggestion').length>0&&shown.filter(r=>r.type==='suggestion').every(r=>selectedNotes.has(r.key))?'checked':''}> <strong>Select all</strong></label>\n         <span>${selectedVisible.length} selected</span>\n         <button type=\"button\" class=\"whdc-editor-bulklink\" data-bulk-notes=\"accept\" ${selectedVisible.length?'':'disabled'}>Accept selected</button>\n         <span>|</span><button type=\"button\" class=\"whdc-editor-bulklink whdc-editor-bulk-danger\" data-bulk-notes=\"reject\" ${selectedVisible.length?'':'disabled'}>Reject selected</button>\n         <span>|</span><button type=\"button\" class=\"whdc-editor-bulklink\" data-bulk-notes=\"clear\">Clear</button>\n       </div>\n       <div class=\"whdc-editor-admin-tabs\">${[['pending','Needs Approval'],['assigned','Assigned'],['to_edit','To Edit'],['completed','Completed'],['all','All']].map(([key,label])=>`<button type=\"button\" class=\"btn ${notesTab===key?'primary':''}\" data-notes-tab=\"${key}\">${label} (${counts[key]})</button>`).join('')}</div>\n       <div class=\"whdc-editor-admin-list\">${shown.map(r=>`<div class=\"whdc-editor-admin-row\">\n          ${r.type==='suggestion'?`<input type=\"checkbox\" class=\"whdc-editor-row-check\" data-select-note=\"${safe(r.key)}\" aria-label=\"Select ${safe(r.title)}\" ${selectedNotes.has(r.key)?'checked':''}>`:`<span class=\"whdc-editor-check-placeholder\"></span>`}\n          <div class=\"whdc-editor-admin-row-content\">\n            <button type=\"button\" class=\"whdc-editor-admin-title\" data-${r.type==='suggestion'?'review-note':'reassign-note'}=\"${safe(r.key)}\">${safe(r.title)}</button>\n            <div class=\"small muted\">${r.source==='writer'?'Guest Writer Devotional':'My Devotional'} · ${r.type==='assignment'?'Assigned editor: ':'Editor: '}${safe(r.email)} · <strong>${safe(r.status)}</strong></div>\n          </div>\n          <div class=\"whdc-editor-admin-actions\">\n            ${r.type==='suggestion'?`<button type=\"button\" class=\"btn\" data-review-note=\"${safe(r.key)}\">Review Edits</button><button type=\"button\" class=\"btn\" data-reassign-note=\"${safe(r.key)}\">Reassign</button>`:`<button type=\"button\" class=\"btn\" data-reassign-note=\"${safe(r.key)}\">Reassign</button>`}\n          </div></div>`).join('')||'<p class=\"whdc-editor-admin-empty\">No devotionals in this tab.</p>'}</div>\n     </div>`;\n     area.querySelectorAll('[data-notes-tab]').forEach(b=>b.onclick=()=>{notesTab=b.dataset.notesTab;show()});\n     area.querySelectorAll('[data-review-note]').forEach(b=>b.onclick=()=>{const s=pending.find(s=>s.source_type+':'+s.devotional_id===b.dataset.reviewNote);if(s)reviewEditorSuggestion(s)});\n     area.querySelectorAll('[data-reassign-note]').forEach(b=>b.onclick=()=>assign(b.dataset.reassignNote));\n     area.querySelectorAll('[data-select-note]').forEach(b=>b.onchange=()=>{if(b.checked)selectedNotes.add(b.dataset.selectNote);else selectedNotes.delete(b.dataset.selectNote);show()});\n     const selectAll=area.querySelector('#selectAllEditorNotes');\n     selectAll.onchange=()=>{for(const r of shown.filter(r=>r.type==='suggestion')){if(selectAll.checked)selectedNotes.add(r.key);else selectedNotes.delete(r.key)}show()};\n     area.querySelectorAll('[data-bulk-notes]').forEach(b=>b.onclick=async()=>{\n       if(b.dataset.bulkNotes==='clear'){selectedNotes.clear();show();return}\n       const chosen=shown.filter(r=>r.type==='suggestion'&&selectedNotes.has(r.key));\n       if(!chosen.length)return;\n       const accept=b.dataset.bulkNotes==='accept';\n       if(!confirm(`${accept?'Accept':'Reject'} editor suggestions for ${chosen.length} devotional(s)?`))return;\n       b.disabled=true;\n       let errors=[];\n       for(const r of chosen){\n         try{\n           const s=r.item,orig=JSON.parse(s.original_json),next=JSON.parse(s.suggested_json);\n           const fields=Object.keys(next).filter(k=>orig[k]!==next[k]);\n           await post('/api/admin/editors/review',{sourceType:s.source_type,id:s.devotional_id,accepted:accept?fields:[]});\n           selectedNotes.delete(r.key);\n         }catch(err){errors.push(r.title+': '+err.message)}\n       }\n       await load();\n       if(errors.length)alert('Some reviews could not be completed:\\n'+errors.join('\\n'));\n     });\n   };\n   window.showEditorNotesPage=show;\n }\n\n mount.style.margin='22px 0';\n if(!submissionsPage && !editorNotesPage){/* Editor management is available through the Editors navigation tab. */}\n const post=(path,data)=>api(path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)});\n async function load(){\n  [editors,assignments,suggestions,roleWriters]=await Promise.all([api('/api/admin/editors'),api('/api/admin/editors/assignments'),api('/api/admin/editors/suggestions'),api('/api/admin/writers')]);\n  renderEditors();\n }\n function renderEditors(){\n  if(editorNotesPage){window.showEditorNotesPage?.();return;}\n  if(submissionsPage)return;\n  mount.innerHTML=`<div class=\"whdc-manage-header\"><h2>Manage Editors <span class=\"small muted\">(${editors.filter(e=>e.active).length} active)</span></h2><button type=\"button\" class=\"btn\" id=\"toggleAddEditor\" aria-controls=\"addEditor\" aria-expanded=\"${showAddEditor}\">${showAddEditor?'Cancel':'＋ Add Editor'}</button></div>\n  <form id=\"addEditor\" class=\"whdc-add-writer-form\" ${showAddEditor?'':'hidden'}><label>Editor name<input name=\"displayName\" required maxlength=\"120\"></label><label>Editor email<input name=\"email\" type=\"email\" required></label><button class=\"btn primary\" type=\"submit\">Add or Reactivate Editor</button></form>\n  <details class=\"whdc-writer-list\" id=\"editorList\" ${showEditorList?'open':''}><summary>View editors (${editors.length})</summary><div class=\"whdc-role-tabs\"><button type=\"button\" class=\"btn ${editorRoleTab==='active'?'primary':''}\" data-editor-role-tab=\"active\">Active (${editors.filter(e=>e.active).length})</button><button type=\"button\" class=\"btn ${editorRoleTab==='inactive'?'primary':''}\" data-editor-role-tab=\"inactive\">Inactive (${editors.filter(e=>!e.active).length})</button></div>${editors.filter(e=>Boolean(e.active)===(editorRoleTab==='active')).map(e=>`<div class=\"whdc-writer-entry\"><span class=\"whdc-editor-identity\"><strong>${safe(e.display_name)}</strong><span class=\"whdc-editor-email\">${safe(e.email)}</span><span class=\"small muted\">${e.active?'Active':'Inactive'}</span></span><div class=\"actions\">${!roleWriters.some(w=>w.active&&w.email===e.email)?`<button class=\"btn\" type=\"button\" data-add-writer-role=\"${safe(e.email)}\">Add Writer Role</button>`:`<span class=\"small muted\">Writer role active</span>`}${e.active?`<button class=\"btn\" type=\"button\" data-editor-resend=\"${safe(e.email)}\">Resend Invitation</button><button class=\"btn\" type=\"button\" data-editor-disable=\"${safe(e.email)}\">Deactivate</button>`:`<button class=\"btn\" type=\"button\" data-editor-activate=\"${safe(e.email)}\">Reactivate</button>`}</div></div>`).join('')||'<p class=\"small muted\">No editors added yet.</p>'}</details>\n`;\n  mount.querySelector('#toggleAddEditor').onclick=()=>{showAddEditor=!showAddEditor;renderEditors()};\n  mount.querySelector('#editorList').ontoggle=e=>{showEditorList=e.target.open};\n  mount.querySelectorAll('[data-editor-role-tab]').forEach(b=>b.onclick=()=>{editorRoleTab=b.dataset.editorRoleTab;showEditorList=true;renderEditors()});\n  const writerBox=document.querySelector('#writerManagement .whdc-manage-compact')||document.querySelector('.whdc-manage-compact');\n  if(writerBox){\n    let grid=document.getElementById('whdcManagementGrid');\n    if(!grid){grid=document.createElement('div');grid.id='whdcManagementGrid';writerBox.before(grid)}\n    grid.append(writerBox,mount);\n  }\n  mount.querySelector('#addEditor').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{const result=await post('/api/admin/editors',{email:f.get('email'),displayName:f.get('displayName')});showAddEditor=false;showEditorList=true;await load();if(!result.alreadyActive)alert(result.invitationSent?'Editor added. Invitation email sent.':'Editor added, but the invitation email could not be confirmed. Use Resend Invitation to retry.')}catch(err){alert(err.message)}};\n  mount.querySelectorAll('[data-add-writer-role]').forEach(b=>b.onclick=async()=>{\n    const e=editors.find(x=>x.email===b.dataset.addWriterRole);\n    if(!e||!confirm('Give '+e.display_name+' a Writer role as well? Their Editor role will stay unchanged.'))return;\n    b.disabled=true;\n    try{\n      const existing=roleWriters.find(w=>w.email===e.email);\n      if(existing){await post('/api/admin/writers/reactivate',{email:e.email})}\n      else{await post('/api/admin/writers',{email:e.email,displayName:e.display_name})}\n      await load();document.dispatchEvent(new Event('whdc-role-updated'));\n      alert('Writer role added. This person can now access their Writer Dashboard.');\n    }catch(err){alert(err.message);b.disabled=false}\n  });\n  mount.querySelectorAll('[data-editor-disable]').forEach(b=>b.onclick=async()=>{if(!confirm('Deactivate this editor and revoke access?'))return;try{await post('/api/admin/editors/deactivate',{email:b.dataset.editorDisable});await load()}catch(err){alert(err.message)}});\n  mount.querySelectorAll('[data-editor-resend]').forEach(b=>b.onclick=async()=>{\n    b.disabled=true;\n    try{\n      const result=await post('/api/admin/editors/resend-invitation',{email:b.dataset.editorResend});\n      alert(result.invitationSent?'Editor invitation email sent.':'Email delivery could not be confirmed. Please check your Google Apps Script deployment.');\n    }catch(err){alert(err.message)}finally{b.disabled=false}\n  });\n  mount.querySelectorAll('[data-editor-activate]').forEach(b=>b.onclick=async()=>{const e=editors.find(x=>x.email===b.dataset.editorActivate);try{const result=await post('/api/admin/editors',{email:e.email,displayName:e.display_name});await load();alert(result.invitationSent?'Editor reactivated. Invitation email sent.':'Editor reactivated, but the invitation email could not be confirmed.')}catch(err){alert(err.message)}});\n }\n\n\nfunction enablePopupFormatting(root){\n root.querySelectorAll('textarea[name=\"short\"],textarea[name=\"deeper\"],textarea[name=\"reflection\"]').forEach(el=>{\n  if(el.dataset.richReady)return;\n  el.dataset.richReady='1';\n  const toolbar=document.createElement('div');\n  toolbar.className='actions whdc-rich-toolbar';\n  toolbar.setAttribute('role','toolbar');\n  toolbar.setAttribute('aria-label','Text formatting');\n  toolbar.innerHTML='<button type=\"button\" class=\"btn\" data-rich-mark=\"**\" aria-label=\"Bold selected text\" title=\"Bold (Ctrl/Cmd+B)\"><strong>B</strong></button><button type=\"button\" class=\"btn\" data-rich-mark=\"*\" aria-label=\"Italicize selected text\" title=\"Italic (Ctrl/Cmd+I)\"><em>I</em></button>';\n  // If a toolbar already exists in the admin editor, do not duplicate it.\n  if(!el.previousElementSibling?.matches('.actions[role=\"toolbar\"]'))el.before(toolbar);\n  else toolbar.remove();\n  const apply=mark=>{\n   const start=el.selectionStart,end=el.selectionEnd;\n   const selected=el.value.slice(start,end),inside=selected||(mark==='**'?'bold text':'italic text');\n   el.setRangeText(mark+inside+mark,start,end,'select');\n   el.focus();el.setSelectionRange(start+mark.length,start+mark.length+inside.length);\n   el.dispatchEvent(new Event('input',{bubbles:true}));\n  };\n  toolbar.querySelectorAll('[data-rich-mark]').forEach(b=>b.addEventListener('click',()=>apply(b.dataset.richMark)));\n  el.addEventListener('keydown',ev=>{\n   if((ev.ctrlKey||ev.metaKey)&&!ev.altKey&&['b','i'].includes(ev.key.toLowerCase())){\n    ev.preventDefault();apply(ev.key.toLowerCase()==='b'?'**':'*');\n   }\n  });\n });\n}\n\nfunction editorWordDiff(before,after){\n const a=String(before??'').match(/\\S+|\\s+/g)||[],b=String(after??'').match(/\\S+|\\s+/g)||[];\n if(a.join('')===b.join(''))return safe(after||'').replace(/\\n/g,'<br>');\n if(a.length*b.length>180000)return '<div class=\"small muted\">Original:</div><div class=\"whdc-track-section\">'+safe(before).replace(/\\n/g,'<br>')+'</div><div class=\"small muted\">Suggested:</div><div class=\"whdc-track-section\"><ins class=\"whdc-editor-added\">'+safe(after).replace(/\\n/g,'<br>')+'</ins></div>';\n const dp=Array.from({length:a.length+1},()=>new Uint32Array(b.length+1));\n for(let i=a.length-1;i>=0;i--)for(let j=b.length-1;j>=0;j--)dp[i][j]=a[i]===b[j]?dp[i+1][j+1]+1:Math.max(dp[i+1][j],dp[i][j+1]);\n let i=0,j=0,html='';\n while(i<a.length||j<b.length){\n  if(i<a.length&&j<b.length&&a[i]===b[j]){html+=safe(a[i]);i++;j++}\n  else if(j<b.length&&(i===a.length||dp[i][j+1]>=dp[i+1][j])){html+='<ins class=\"whdc-editor-added\">'+safe(b[j++])+'</ins>'}\n  else{html+='<del class=\"whdc-editor-removed\">'+safe(a[i++])+'</del>'}\n }\n return html.replace(/\\n/g,'<br>');\n}\n\n function reviewEditorSuggestion(s){\n  const original=JSON.parse(s.original_json),suggested=JSON.parse(s.suggested_json);\n  const names={title:'Title',reference:'Scripture Reference',short:'Devotional',deeper:'Go Deeper',reflection:'Reflection Questions'};\n  const changed=Object.keys(names).filter(k=>String(original[k]??'')!==String(suggested[k]??''));\n  const dialog=document.createElement('dialog');\n  dialog.className='whdc-review-dialog whdc-editor-review-dialog';\n  dialog.innerHTML=`<div class=\"whdc-review-dialog-inner\"><div class=\"whdc-review-dialog-body\">\n    <h2>Review Editor Changes</h2>\n    <p class=\"small muted\">${safe(s.devotional_title||original.title||s.devotional_id)} · Editor: ${safe(s.editor_email)}</p>\n    <p class=\"whdc-track-legend\"><span class=\"whdc-editor-added\">Red underline</span> = added or changed words · <span class=\"whdc-editor-removed\">Red strikethrough</span> = removed words</p>\n    ${changed.map(k=>`<section class=\"whdc-editor-diff-field\"><h3>${safe(names[k])}</h3><div class=\"whdc-track-section\">${editorWordDiff(original[k],suggested[k])}</div></section>`).join('')||'<p>No differences to review.</p>'}\n    </div><div class=\"whdc-review-dialog-footer\"><div class=\"actions\">\n    <button type=\"button\" class=\"btn primary\" id=\"acceptEditorEdits\">Accept Edits</button>\n    <button type=\"button\" class=\"btn\" id=\"rejectEditorEdits\">Reject Edits</button>\n    <button type=\"button\" class=\"btn\" id=\"closeEditorEdits\">Close</button>\n    </div><p class=\"small muted\" id=\"editorReviewStatus\" aria-live=\"polite\"></p></div></div>`;\n  document.body.appendChild(dialog);dialog.showModal();\n  const close=()=>{dialog.close();dialog.remove()};\n  dialog.querySelector('#closeEditorEdits').onclick=close;\n  const review=async accept=>{\n    if(!confirm(accept?'Accept ALL suggested edits to this devotional?':'Reject ALL suggested edits without changing the devotional?'))return;\n    const buttons=dialog.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);\n    try{\n      await post('/api/admin/editors/review',{sourceType:s.source_type,id:s.devotional_id,accepted:accept?changed:[]});\n      close();await load();await refresh();\n    }catch(err){dialog.querySelector('#editorReviewStatus').textContent=err.message;buttons.forEach(b=>b.disabled=false)}\n  };\n  dialog.querySelector('#acceptEditorEdits').onclick=()=>review(true);\n  dialog.querySelector('#rejectEditorEdits').onclick=()=>review(false);\n }\n async function assign(value){\n  const [sourceType,...rest]=value.split(':'),id=rest.join(':');\n  if(!editors.length)await load();\n  const active=editors.filter(e=>e.active);\n  if(!active.length){alert('Add an active editor in Manage Editors first.');return}\n  const existing=assignments.find(a=>a.source_type===sourceType&&a.devotional_id===id);\n  const dialog=document.createElement('dialog');dialog.style.cssText='width:min(500px,95vw);border:0;border-radius:12px;padding:24px';\n  dialog.innerHTML=`<h2>Assign Devotional</h2><p>${safe(id)}</p><label>Editor<select id=\"editorChoice\"><option value=\"\">Unassign</option>${active.map(e=>`<option value=\"${safe(e.email)}\" ${existing?.editor_email===e.email?'selected':''}>${safe(e.display_name)} (${safe(e.email)})</option>`).join('')}</select></label><div class=\"actions\"><button class=\"btn primary\" id=\"saveEditorAssignment\">Save Assignment</button><button class=\"btn\" id=\"cancelEditorAssignment\">Cancel</button></div>`;\n  document.body.appendChild(dialog);dialog.showModal();\n  const close=()=>{dialog.close();dialog.remove()};\n  dialog.querySelector('#cancelEditorAssignment').onclick=close;\n  dialog.querySelector('#saveEditorAssignment').onclick=async()=>{try{const result=await post('/api/admin/editors/assign',{sourceType,id,email:dialog.querySelector('#editorChoice').value});close();await load();if(result.emailSent===false)alert('Assignment saved, but the notification email could not be confirmed. Please contact the editor directly.')}catch(err){alert(err.message)}};\n }\n document.addEventListener('click',e=>{const b=e.target.closest('[data-assign-editor]');if(b){e.preventDefault();assign(b.dataset.assignEditor).catch(err=>alert(err.message))}});\n document.addEventListener('whdc-role-updated',()=>load().catch(()=>{}));\n load().catch(e=>{if(!submissionsPage)mount.innerHTML='<h2>Manage Editors</h2><p>'+safe(e.message)+'</p>'});\n})();\n\n" + TEAM_MANAGEMENT_JS + "\n\nfunction openPublishedPreview(devotional){\n const old=document.getElementById('whdcPublishedPreviewDialog');if(old)old.remove();\n const dialog=document.createElement('dialog');dialog.id='whdcPublishedPreviewDialog';\n dialog.style.cssText='width:min(1100px,96vw);height:92vh;max-height:92vh;border:0;border-radius:14px;padding:0;box-shadow:0 18px 65px #0006';\n dialog.innerHTML='<div style=\"display:flex;align-items:center;justify-content:space-between;padding:12px 18px;border-bottom:1px solid #ddd;gap:12px\"><strong>Published App Preview</strong><button type=\"button\" class=\"btn\" id=\"closePublishedPreview\">Close</button></div><iframe title=\"Published devotional preview\" src=\"/?whdcPreview=1\" style=\"display:block;border:0;width:100%;height:calc(100% - 64px)\"></iframe>';\n document.body.appendChild(dialog);\n const frame=dialog.querySelector('iframe');\n const ready=event=>{if(event.origin!==location.origin||event.source!==frame.contentWindow||event.data?.type!=='whdc-preview-ready')return;frame.contentWindow.postMessage({type:'whdc-preview-devotional',devotional},location.origin)};\n window.addEventListener('message',ready);\n dialog.addEventListener('close',()=>{window.removeEventListener('message',ready);dialog.remove()},{once:true});\n dialog.querySelector('#closePublishedPreview').onclick=()=>dialog.close();\n dialog.showModal();\n}\n";
